/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
public class METInventTransferTableExt extends common
{
}

Method.Source:
/// <summary>
/// insert record
/// </summary>
public void insert()
{
    if(this.InventTransferTable)
    {
        this.setInternalCustomer();
        super();                   
    }
}

    /// <summary>
    /// CB866_TOHandleSplitandOptimisation.
    /// Sets internal customer.
    /// </summary>
    /// <param name = "_inventLocationId">InventLocationId. </param>
    public void setInternalCustomer(InventLocationId _inventLocationId = '')
    {
        METInventLocation metInventLocation;
        InventTransferTable transferTable;
        InventLocationIdTo inventLocationIdTo;
        METSalesTable      metSalesTable = METSalesTable::findBySalesId(this.SalesId);
        
        // If transfer type is internal cross dock and salesorder is linked updated the Door value from salestable secoundary door number
        if (this.TransferType == METCrossDockTransferType::CrossDock  
            && metSalesTable.InternalCrossDockOrder == NoYes::Yes)
        {
            this.Door = any2Str(metSalesTable.SecondaryDoorNum);
        }

        if (this.TransferType != METCrossDockTransferType::None || this.InternalCustomer != '')
        {
            return;
        }

        inventLocationIdTo = (_inventLocationId) ? _inventLocationId : InventTransferTable::findRecId(this.InventTransferTable).InventLocationIdTo;
        metInventLocation = METInventLocation::findByInventLocationId(inventLocationIdTo);

        this.InternalCustomer = metInventLocation.LocalInternalCustomer;
    }

    /// <summary>
    /// Are backorders allowed on a Transfer order, find by route Id
    /// </summary>
    /// <param name = "_pickingRouteId">Route Id</param>
    /// <returns>True/false</returns>
    public static boolean isAllowBackorderRouteId(WMSPickingRouteID _pickingRouteId)
    {
        boolean allowed = false;
    
        WMSPickingRoute             pickingRoute;
        InventTransferTable         inventTransferTable;
        METInventTransferTableExt   inventTransferTableExt;

        while select firstonly pickingRouteID from pickingRoute
            where   pickingRoute.pickingRouteID == _pickingRouteId

            exists  join inventTransferTable
            where   inventTransferTable.TransferId == pickingRoute.transRefId

            exists  join inventTransferTableExt
            where   inventTransferTableExt.InventTransferTable   == inventTransferTable.RecId
            &&      inventTransferTableExt.AllowBackorder        == NoYes::Yes
        {
            allowed = true;
        }

        return allowed;
    }

    /// <summary>
    /// get auto extract value
    /// </summary>
    /// <param name = "_metInventLocationIdFrom">from warehouse</param>
    /// <param name = "_metInventLocationIdTo">to warehouse</param>
    /// <returns>True/false</returns>
    public static METAutoExtract metIsAutoExtract(InventLocationIdFrom _metInventLocationIdFrom, InventLocationIdTo _metInventLocationIdTo)
    {
        METAutoExtract metAutoExtract = NoYes::No;

        if(InventLocation::metGetAutoExtract(_metInventLocationIdFrom) && InventLocation::metGetAutoExtract(_metInventLocationIdTo))
        {
            metAutoExtract = NoYes::yes;
        }

        return metAutoExtract;
    }

/// <summary>
/// Set Extraction status
/// </summary>
 public void  setExtractionStatus()
{
    this.OrderExtractStatus = this.AutoExtract == NoYes::Yes ? METOrderExtractStatus::ReadyForExtract : METOrderExtractStatus::Open;
}

    /// <summary>
    /// Update Extract status
    /// </summary>
    /// <param name = "_transferId">Transfer order id</param>
    public static void UpdateExtractionStatus(InventTransferId  _transferId)
    {
        InventTransferTable         inventTransferTable;
        METInventTransferTableExt   inventTransferTableExt;
        InventTransferLine          inventTransferLine;
        METInventTransferLine       metInventTransferLine;

        select minof(OrderExtractStatus) from metInventTransferLine
            exists join inventTransferLine
                where inventTransferLine.TransferId == _transferId
                    && metInventTransferLine.InventTransferLine == inventTransferLine.RecId;

        select firstonly forupdate inventTransferTableExt
            join RecId from inventTransferTable
            where inventTransferTable.RecId == inventTransferTableExt.InventTransferTable
            && inventTransferTable.TransferId == _transferId;

        if (inventTransferTableExt && inventTransferTableExt.OrderExtractStatus != metInventTransferLine.OrderExtractStatus)
        {
            ttsbegin;
            inventTransferTableExt.OrderExtractStatus = metInventTransferLine.OrderExtractStatus;
            inventTransferTableExt.update();
            ttscommit;
        }
  
    }

    [SysClientCacheDataMethodAttribute(true)]
    display METAllowSubstitution displayAllowSubstitution()
    {
        METInventTransferLine metTransferLine;
        InventTransferLine transferLine;
        InventTransferTable transferTable;

        select firstonly RecId from metTransferLine
            where metTransferLine.AllowSubstitution == NoYes::Yes
            exists join transferLine
            where transferLine.RecId == metTransferLine.InventTransferLine
            exists join transferTable
            where transferTable.RecId == this.InventTransferTable
            &&    transferTable.TransferId == transferLine.TransferId;

        return metTransferLine.RecId != 0;
    }

    /// <summary>
    /// CB395_CSDFulfilementInterBranchTransfer.
    /// Finds and return <c>METInventTransferTableExt</c> record.
    /// </summary>
    /// <param name = "_transferId">Transfer Id.</param>
    /// <param name = "_forUpdate">ForUpdate.</param>
    /// <returns><c>METInventTransferTableExt</c> record.</returns>
    public static METInventTransferTableExt findByTransferId(InventTransferId _transferId, boolean _forUpdate = false)
    {
        METInventTransferTableExt metTransferTable;
        InventTransferTable       transferTable;

        metTransferTable.selectForUpdate(_forUpdate);

        select firstonly metTransferTable
            exists join transferTable
                where transferTable.RecId == metTransferTable.InventTransferTable
                &&    transferTable.TransferId == _transferId;

        return metTransferTable;
    }

    /// <summary>
    /// Update record
    /// </summary>
    public void update()
    {
        METInventTransferTableExt   metTransferTableOrig    = this.orig();
        InventParameters inventParameters = InventParameters::find();

        super();
        
        //CB627_TMSEngineProcessingTOCreation
        if(metTransferTableOrig.IOMSyncCompleted == NoYes::No && this.IOMSyncCompleted == NoYes::Yes)
        {  
            InventTransferId transferId = InventTransferTable::findRecId(this.InventTransferTable).TransferId;

            // Build controller
            METTMSProcessingStatus::insertTMSProcessingStatus(METTMSOrderType::TransferOrder, transferId, METTMSEngineExecutionMode::TransferOrderCreation);
        }

        if (this.OrderExtractStatus == METOrderExtractStatus::Extracted)
        {
            this.updateWaveStatus();
        }
    }

