/// <summary>
/// Method to get last pick list generated for sales order
/// </summary>
/// <param name = "_metInventTransferTableExt">InventTransferTable ext</param>
/// <returns>WMSPickingRoute</returns>
public static WMSPickingRoute getLastPickListInfo(METInventTransferTableExt     _metInventTransferTableExt)
{
    WMSPickingRoute     wmsPickingRoute;
    InventTransferTable inventTransferTable = InventTransferTable::findRecId(_metInventTransferTableExt.InventTransferTable);
        
    select firstonly pickingRouteID, CreatedDateTime, CreatedBy from wmsPickingRoute
        order by CreatedDateTime desc
            exists join inventTransferTable
                where inventTransferTable.TransferId == wmsPickingRoute.transRefId      &&
                    wmsPickingRoute.transType == InventTransType::TransferOrderShip     &&
                    inventTransferTable.RecId == _metInventTransferTableExt.InventTransferTable;
                
    return wmsPickingRoute;
}

    /// <summary>
    /// Validate inventtransfer table fields
    /// </summary>
    /// <param name = "_fieldIdToCheck">field to check</param>
    /// <returns>return true or false based on validations</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);

        switch(_fieldIdToCheck)
        {
            Case fieldNum(METInventTransferTableExt, Route):

                METValidateRouteHelper validateRouteHelper = new METValidateRouteHelper();
                
                if (!validateRouteHelper.validateRouteForUpperCase(this.Route) || !validateRouteHelper.validateRouteLength(strLen(this.Route)) ||
                    !validateRouteHelper.validateForAlphaNumeric(this.Route))
                {
                    ret = false;
                }
                break;

            case fieldNum(METInventTransferTableExt, RouteStopNum):      
          
                METValidateRouteHelper validateRouteHelperLoc = new METValidateRouteHelper();
                ret = validateRouteHelperLoc.validateRouteStop(this.RouteStopNum, strLen(int2Str(this.RouteStopNum)));
                break;

            case fieldNum(METInventTransferTableExt, InternalCustomer):
          
                CustTable custtable = CustTable::find(this.InternalCustomer) ;
                if (!custtable)
                {
                    ret = checkFailed("@MET:InvalidCustomeraccount");
                }
                break;
        }

        return ret;
    }

    /// <summary>
    /// Update wave status if all lines on transfer order are extracted
    /// </summary>
    public void updateWaveStatus()
    {
        METWaveTable    metWaveTable;
        METWaveLine     metWaveLine;
        METDocumentNum  metDocumentNum;
        METWaveId       metWaveId;
        METInventTransferTableExt   metInventTransferTableExt;
        InventTransferTable inventTransferTableLoc;

        InventTransferTable inventTransferTable = InventTransferTable::findRecId(this.InventTransferTable);

        select firstonly1 WaveId from metWaveLine
            where metWaveLine.DocumentNumber == inventTransferTable.TransferId;

        metWaveId = metWaveLine.WaveId;

        if (metWaveId == '')
        {
            return;
        }

        select firstonly RecId from metWaveLine
                where metWaveLine.WaveId == metWaveId &&
                    metWaveLine.Type == METType::TransferOrder
            exists join inventTransferTableLoc
                where inventTransferTableLoc.TransferId == metWaveLine.DocumentNumber
            exists join metInventTransferTableExt
                where metInventTransferTableExt.InventTransferTable == inventTransferTableLoc.RecId
                && metInventTransferTableExt.OrderExtractStatus != METOrderExtractStatus::Extracted;

        if (metWaveLine.RecId == 0)
        {
            ttsbegin;
            metWaveTable = METWaveTable::find(metWaveId, true);

            if (metWavetable.RecId)
            {
                metWaveTable.WaveStatus = METCSDWaveStatus::Extracted;
                metWaveTable.update();

                Info(strFmt("@MET:WaveStatusUpdate", metWaveId));
            }
            ttscommit;
        }

    }

    /// <summary>
    /// Determines if the given warehouse is a Campbells warehouse.
    /// </summary>
    /// <param name="_inventLocationId">Warehouse ID to check.</param>
    /// <returns>True if Campbells warehouse, otherwise false.</returns>
    public static boolean isCampbellsWarehouse(InventLocationId _inventLocationId)
    {
        InventLocation inventLocation = InventLocation::find(_inventLocationId);

        return inventLocation.METWHSubEntity == WHSParameters::find().METCampbellSubEntityIndustryKey;
    }
